<details class="ff-settings-group" :open="inspectorSections.data" x-on:toggle="inspectorSections.data=$event.target.open">
<summary><span class="ff-settings-label"><span class="ff-heading-icon" x-html="iconSvg('database')"></span>{{ __('filaforge::studio.data_title') }}</span><span class="ff-settings-chevron" x-html="iconSvg('chevron-down')"></span></summary>
<div class="ff-settings-content ff-data-settings">
<p class="ff-muted">{{ __('filaforge::studio.data_bound_hint') }}</p>
<template x-if="find(selected)?.type==='query-loop'"><div class="ff-data-group">
<h3>{{ __('filaforge::studio.data_loop') }}</h3>
<label class="ff-source-field"><span>{{ __('filaforge::studio.data_source') }}</span><select :value="find(selected)?.props.provider" x-on:change="setLoop('provider',$event.target.value)"><template x-for="source in sources" :key="source.name"><option :value="source.name" :selected="find(selected)?.props.provider===source.name" x-text="source.label"></option></template></select></label>
<label class="ff-source-field"><span>{{ __('filaforge::studio.data_limit') }}</span><input type="number" min="1" :max="source(find(selected)?.props.provider)?.maxLimit||24" :value="find(selected)?.props.query.limit||6" x-on:change="setLoop('limit',Number($event.target.value))"></label>
<label class="ff-source-field"><span>{{ __('filaforge::studio.data_sort') }}</span><select :value="find(selected)?.props.query.sort||''" x-on:change="setLoop('sort',$event.target.value||null)"><option value="">{{ __('filaforge::studio.data_default') }}</option><template x-for="(label,key) in (source(find(selected)?.props.provider)?.sorts||{})" :key="key"><option :value="key" :selected="find(selected)?.props.query.sort===key" x-text="label"></option></template></select></label>
<label class="ff-source-field"><span>{{ __('filaforge::studio.data_empty_text') }}</span><input :value="find(selected)?.props.emptyText||''" maxlength="1000" x-on:change="setLoop('emptyText',$event.target.value)"></label>
<template x-if="source(find(selected)?.props.provider)?.filters?.length"><div class="ff-data-group"><h3>{{ __('filaforge::studio.data_filters') }}</h3><select class="ff-search" x-model="loopFilterKey"><option value="">{{ __('filaforge::studio.data_filters') }}</option><template x-for="key in source(find(selected)?.props.provider).filters"><option :value="key" x-text="key"></option></template></select><input class="ff-search" x-model="loopFilterValue" maxlength="500" aria-label="{{ __('filaforge::studio.data_filter_value') }}"><button type="button" class="ff-btn" x-on:click="addLoopFilter()" :disabled="!loopFilterKey">{{ __('filaforge::studio.data_filter_add') }}</button><template x-for="(value,key) in (find(selected)?.props.query.filters||{})"><div class="ff-data-filter"><span x-text="key+': '+value"></span><button type="button" class="ff-source-link" x-on:click="removeLoopFilter(key)" aria-label="{{ __('filaforge::studio.data_filter_remove') }}">×</button></div></template></div></template>
</div></template>
<template x-if="find(selected)?.type==='shortcode'"><div class="ff-data-group"><h3>{{ __('filaforge::studio.data_component') }}</h3><div class="ff-picker-current"><strong x-text="dataComponents.find(c=>c.name===find(selected)?.props.name)?.label||find(selected)?.props.name"></strong><button type="button" class="ff-source-link" x-on:click="openDataPicker('',true)">{{ __('filaforge::studio.picker_change') }}</button></div><template x-for="key in (dataComponents.find(c=>c.name===find(selected)?.props.name)?.arguments||[])"><label class="ff-source-field"><span x-text="key"></span><input :value="find(selected)?.props.arguments?.[key]||''" maxlength="1000" x-on:change="setShortcodeArgument(key,$event.target.value)"></label></template></div></template>
<template x-if="(dataSlots[find(selected)?.type]||[]).length"><div class="ff-data-group"><h3>{{ __('filaforge::studio.data_binding') }}</h3>
<button type="button" class="ff-btn ff-picker-launch" x-on:click="openDataPicker(bindingSlot||(dataSlots[find(selected)?.type]||[])[0])">{{ __('filaforge::studio.picker_connect') }}</button>
<div class="ff-picker-current" x-show="binding()"><span x-text="(binding()?.provider==='@item'?@js(__('filaforge::studio.data_item')):source(binding()?.provider)?.label||'')+' · '+(fieldsFor(binding()?.provider)?.[binding()?.field]?.label||'')"></span><button type="button" class="ff-source-link" x-on:click="setBinding('provider','')">{{ __('filaforge::studio.data_remove') }}</button></div>
<details class="ff-data-advanced"><summary>{{ __('filaforge::studio.picker_more') }}</summary>
<label class="ff-source-field"><span>{{ __('filaforge::studio.data_property') }}</span><select x-model="bindingSlot"><option value="">—</option><template x-for="slot in dataSlots[find(selected)?.type]"><option :value="slot" x-text="dataLabel('slot',slot)"></option></template></select></label>
<div class="ff-data-fields" x-show="bindingSlot"><label class="ff-source-field"><span>{{ __('filaforge::studio.data_source') }}</span><select :value="binding()?.provider||''" x-on:change="setBinding('provider',$event.target.value)"><option value="">{{ __('filaforge::studio.data_none') }}</option><template x-for="source in availableSources()"><option :value="source.name" :selected="binding()?.provider===source.name" x-text="source.label"></option></template></select></label>
<template x-if="binding()"><div class="ff-data-fields"><label class="ff-source-field"><span>{{ __('filaforge::studio.data_field') }}</span><select :value="binding().field" x-on:change="setBinding('field',$event.target.value)"><template x-for="(definition,key) in fieldsFor(binding().provider)"><option :value="key" :selected="binding()?.field===key" x-text="definition.label||key"></option></template></select></label>
<label class="ff-source-field"><span>{{ __('filaforge::studio.data_formatter') }}</span><select :value="binding().formatter||'text'" x-on:change="setBinding('formatter',$event.target.value)"><template x-for="name in dataFormatters"><option :value="name" :selected="(binding()?.formatter||'text')===name" x-text="dataLabel('format',name)"></option></template></select></label>
<label class="ff-source-field"><span>{{ __('filaforge::studio.data_fallback') }}</span><input :value="binding().fallback||''" maxlength="20000" x-on:change="setBinding('fallback',$event.target.value)"></label></div></template></div>
</details>
</div></template>
<details class="ff-data-group ff-data-advanced"><summary>{{ __('filaforge::studio.data_visibility') }}</summary><label class="ff-source-field"><span>{{ __('filaforge::studio.data_source') }}</span><select :value="find(selected)?.visibility?.provider||''" x-on:change="setVisibility('provider',$event.target.value)"><option value="">{{ __('filaforge::studio.data_none') }}</option><template x-for="source in availableSources()"><option :value="source.name" :selected="find(selected)?.visibility?.provider===source.name" x-text="source.label"></option></template></select></label>
<template x-if="find(selected)?.visibility?.provider"><div class="ff-data-fields"><label class="ff-source-field"><span>{{ __('filaforge::studio.data_field') }}</span><select :value="find(selected).visibility.field" x-on:change="setVisibility('field',$event.target.value)"><template x-for="(definition,key) in fieldsFor(find(selected).visibility.provider)"><option :value="key" :selected="find(selected)?.visibility?.field===key" x-text="definition.label||key"></option></template></select></label>
<label class="ff-source-field"><span>{{ __('filaforge::studio.data_operator') }}</span><select :value="find(selected).visibility.operator" x-on:change="setVisibility('operator',$event.target.value)">@foreach(['eq','neq','gt','gte','lt','lte','contains','empty','not_empty'] as $operator)<option value="{{ $operator }}">{{ __('filaforge::studio.data_'.$operator) }}</option>@endforeach</select></label>
<label class="ff-source-field" x-show="!['empty','not_empty'].includes(find(selected)?.visibility?.operator)"><span>{{ __('filaforge::studio.data_value') }}</span><input :value="find(selected)?.visibility?.value??''" maxlength="1000" x-on:change="setConditionValue($event.target.value)"></label></div></template></details>
<button type="button" class="ff-btn ff-picker-launch" x-on:click="openDataPicker()"><span class="ff-heading-icon" x-html="iconSvg('circle-plus')"></span>{{ __('filaforge::studio.picker_add') }}</button>
</div></details>
